# Path normalization helper function
function Normalize-Path {
    param(
        [string]$Path,
        [string]$TargetFormat = "flutter",
        [bool]$Debug = $false
    )
    
    if ([string]::IsNullOrWhiteSpace($Path)) {
        return $Path
    }
    
    $Path = $Path.Trim()
    
    if ($Debug) {
        Write-Host "[PATH] Input: '$Path'" -ForegroundColor Gray
    }
    
    if ($TargetFormat -eq "flutter" -or $TargetFormat -eq "auto") {
        $Path = $Path -replace "\\+", "/"
        $Path = $Path -replace "\", "/"
        $Path = $Path -replace "/+", "/"
    }
    elseif ($TargetFormat -eq "windows") {
        $Path = $Path -replace "/+", "\"
        $Path = $Path -replace "/", "\"
        $Path = $Path -replace "\+", "\"
    }
    
    if ($Path.StartsWith("/") -and -not $Path.StartsWith("//")) {
        $Path = $Path.Substring(1)
    }
    if ($Path.StartsWith("\") -and -not $Path.StartsWith("\\")) {
        $Path = $Path.Substring(1)
    }
    
    if ($Debug) {
        Write-Host "[PATH] Output: '$Path'" -ForegroundColor Gray
    }
    
    return $Path
}

# Flutter command path fix helper function
function Fix-FlutterCommandPath {
    param(
        [string]$Command,
        [bool]$Debug = $false
    )
    
    if ([string]::IsNullOrWhiteSpace($Command)) {
        return $Command
    }
    
    if ($Debug) {
        Write-Host "[CMD] Original: '$Command'" -ForegroundColor Gray
    }
    
    $Command = $Command -replace " -t ([^\s]+)", {
        $path = $matches[1]
        $normalizedPath = Normalize-Path -Path $path -TargetFormat "flutter" -Debug $Debug
        " -t $normalizedPath"
    }
    
    if ($Debug) {
        Write-Host "[CMD] Fixed: '$Command'" -ForegroundColor Gray
    }
    
    return $Command
}


Write-Host "[BUILD] Starting Flutter build process..." -ForegroundColor Yellow

# Execute Flutter command with real-time output (no buffering)
Write-Host "[BUILD] Executing: flutter build apk --release" -ForegroundColor Cyan
Write-Host "[BUILD] Starting real-time output..." -ForegroundColor Yellow

# Execute command with real-time output
$process = Start-Process -FilePath "powershell" -ArgumentList "-Command", "flutter build apk --release" -NoNewWindow -PassThru -RedirectStandardOutput "build_output.log" -RedirectStandardError "build_error.log"

# Monitor process and show real-time output
while (-not $process.HasExited) {
    Start-Sleep -Milliseconds 100
    if (Test-Path "build_output.log") {
        Get-Content "build_output.log" -Tail 10 | ForEach-Object { Write-Host $_ -ForegroundColor White }
    }
    if (Test-Path "build_error.log") {
        Get-Content "build_error.log" -Tail 5 | ForEach-Object { Write-Host $_ -ForegroundColor Red }
    }
}

$exitCode = $process.ExitCode

# Show final output
if (Test-Path "build_output.log") {
    Write-Host "[BUILD] Final output:" -ForegroundColor Cyan
    Get-Content "build_output.log" | ForEach-Object { Write-Host $_ -ForegroundColor White }
}

if (Test-Path "build_error.log") {
    Write-Host "[BUILD] Error output:" -ForegroundColor Red
    Get-Content "build_error.log" | ForEach-Object { Write-Host $_ -ForegroundColor Red }
}

# Clean up log files
Remove-Item "build_output.log" -ErrorAction SilentlyContinue
Remove-Item "build_error.log" -ErrorAction SilentlyContinue

if ($exitCode -eq 0) {
    Write-Host "[BUILD] Command completed successfully" -ForegroundColor Green

    # Scan for APK files after successful build
    Write-Host "[BUILD] Scanning for APK files..." -ForegroundColor Cyan
    $apkSearchPaths = @(
                "build/app/outputs/flutter-apk",
    )

    $foundApks = @()
    foreach ($searchPath in $apkSearchPaths) {
        $fullPath = Join-Path (Get-Location) $searchPath
        if (Test-Path $fullPath) {
            $apkFiles = Get-ChildItem -Path $fullPath -Filter "*.apk" -File
            foreach ($apk in $apkFiles) {
                $foundApks += $apk.FullName
            }
        }
    }

    if ($foundApks.Count -gt 0) {
        Write-Host "[BUILD] Found APK files:" -ForegroundColor Green
        foreach ($apk in $foundApks) {
            Write-Host "[BUILD]   $apk" -ForegroundColor Gray
        }
    } else {
        Write-Host "[BUILD] No APK files found in expected locations" -ForegroundColor Yellow
    }
} else {
    Write-Host "[BUILD] Command failed with exit code: $exitCode" -ForegroundColor Red
}

Write-Host "[BUILD] Build process completed with exit code: $exitCode" -ForegroundColor $(if ($exitCode -eq 0) { "Green" } else { "Red" })
exit $exitCode
